insert into public.source_documents (raw_filename, sha256, page_count, sport_slug, imported, notes, reviewed_at)
select raw_filename, sha256, page_count, sport_slug, imported, notes, reviewed_at from seed_update_sources
on conflict (tenant_id, raw_filename) do update set sha256 = excluded.sha256, page_count = excluded.page_count, sport_slug = excluded.sport_slug, imported = excluded.imported, notes = excluded.notes, reviewed_at = excluded.reviewed_at, archived_at = null;

