insert into public.groups (tournament_id, name_vi, name_en, sort_order)
select t.id, source.name_vi, source.name_en, source.sort_order
from seed_update_groups source join public.sports s on s.slug = source.sport_slug and s.tenant_id = private.seed_tenant_id()
join public.tournaments t on t.sport_id = s.id and t.slug = source.tournament_slug
on conflict (tournament_id, name_vi) do update set name_en = excluded.name_en, sort_order = excluded.sort_order, archived_at = null;

