update public.fixtures f set starts_at = source.starts_at, round_vi = case when source.scope in ('group','knockout') then source.round_vi else f.round_vi end
from seed_update_schedule source join public.sports s on s.slug = source.sport_slug and s.tenant_id = private.seed_tenant_id()
join public.tournaments t on t.sport_id = s.id and t.slug = source.tournament_slug
where f.tournament_id = t.id
  and ((source.scope = 'group' and f.group_id is not null)
    or (source.scope = 'knockout' and f.group_id is null and f.round_vi ilike any (array['%vòng%', '%tứ%', '%bán%', '%chung%']))
    or (source.scope = 'all' and f.round_vi = 'Thi đấu')
    or (source.scope = 'chess_early' and f.round_order = 1)
    or (source.scope = 'chess_late' and f.round_order = 2)
    or (source.scope = 'early' and f.source_code ~ '^[0-9]+$' and f.source_code::integer <= case when source.tournament_slug = 'nam' then 13 else 8 end)
    or (source.scope = 'late' and f.source_code ~ '^[0-9]+$' and f.source_code::integer > case when source.tournament_slug = 'nam' then 13 else 8 end));

