update public.tournaments t set source_metadata = coalesce(t.source_metadata, '{}'::jsonb) || source.metadata
from seed_update_metadata source
join public.sports s on s.slug = source.sport_slug and s.tenant_id = private.seed_tenant_id()
where t.sport_id = s.id and t.slug = source.tournament_slug and t.tenant_id = s.tenant_id;

-- Normalize source/update spellings before exporting the current workbook snapshot.
select private.merge_entry_variants(private.seed_tenant_id());
select private.archive_obsolete_pickleball_pair(private.seed_tenant_id());

-- Register these reviewed current snapshots so the delivered workbooks can be re-imported safely.
create temporary table seed_update_exports (export_id uuid, sport_slug text) on commit drop;
insert into seed_update_exports values
  ('7a000001-0000-4000-8000-000000000001','pickleball'),
  ('7a000002-0000-4000-8000-000000000002','bong-ban'),
  ('7a000003-0000-4000-8000-000000000003','cau-long'),
  ('7a000004-0000-4000-8000-000000000004','boi-loi'),
  ('7a000005-0000-4000-8000-000000000005','keo-co'),
  ('7a000006-0000-4000-8000-000000000006','dien-kinh'),
  ('7a000007-0000-4000-8000-000000000007','co-vua'),
  ('7a000008-0000-4000-8000-000000000008','co-tuong');
insert into public.sport_excel_exports (id, tenant_id, sport_id, template_version, mode, payload, created_by)
select source.export_id, private.seed_tenant_id(), s.id, 1, 'current', private.sport_excel_snapshot(private.seed_tenant_id(), s.id), admin.user_id
from seed_update_exports source
join public.sports s on s.slug = source.sport_slug and s.tenant_id = private.seed_tenant_id()
join public.admin_users admin on admin.tenant_id = s.tenant_id and admin.archived_at is null
where admin.user_id = (select candidate.user_id from public.admin_users candidate where candidate.tenant_id = s.tenant_id and candidate.archived_at is null order by candidate.display_name limit 1)
on conflict (id) do update set tenant_id = excluded.tenant_id, sport_id = excluded.sport_id, template_version = excluded.template_version, mode = excluded.mode, payload = excluded.payload, created_by = excluded.created_by, archived_at = null;
